// Run against the local test page generated by tests/build-ui-fixture.mjs.
// Uses the Playwright page supplied by playwright-cli; no production test hooks.
export default async function check(page) {
  const assert=(value,message)=>{if(!value)throw new Error(message);};
  await page.setViewportSize({width:1000,height:900});
  assert(await page.locator('#turnList .turn').count()===63,'All 63 rounds must be accessible');
  await page.locator('#roundSelect').click();
  await page.locator('#roundOptions [data-id="t1"]').click();
  assert((await page.locator('#scope').textContent()).includes('第 1 轮'),'Select earliest round');
  assert((await page.locator('#breakdown').textContent()).includes('1,000 tokens'),'Early round cache details');
  await page.evaluate(()=>{window.savedRow=document.querySelector('#turnList [data-id="t1"]');window.testReceive({_meta:{usage:{...window.testUsage,observedAt:Date.now()}}});});
  assert(await page.evaluate(()=>window.savedRow===document.querySelector('#turnList [data-id="t1"]')),'Polling must preserve row identity');
  assert(await page.locator('#roundSelect').getAttribute('data-value')==='t1','Polling must not reset selection');
  await page.locator('#nextTurn').click();
  assert(await page.locator('#roundSelect').getAttribute('data-value')==='t2','Next round');
  await page.locator('#prevTurn').click();
  assert(await page.locator('#roundSelect').getAttribute('data-value')==='t1','Previous round');
  await page.locator('#overviewTab').click();
  await page.locator('#historyRows [data-id="t5"] td').nth(2).click();
  assert(await page.locator('#meterView').isVisible(),'Clicking cost cell opens detail');
  assert(await page.locator('#roundSelect').getAttribute('data-value')==='t5','Cost-cell selection');
  assert((await page.locator('#breakdown').textContent()).includes('5,000 tokens'),'Selected cache detail');
  await page.locator('#overviewTab').click();
  await page.locator('#historyRows [data-id="t3"]').focus();
  await page.keyboard.press('Enter');
  assert(await page.locator('#roundSelect').getAttribute('data-value')==='t3','Keyboard access to historical detail');
  await page.locator('#latestTurn').click();
  assert(await page.locator('#roundSelect').getAttribute('data-value')==='t63','Return to live round');
  await page.screenshot({path:'output/playwright/refined-light.png',fullPage:true});
  await page.setViewportSize({width:390,height:844});
  assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'No narrow overflow');
  await page.emulateMedia({colorScheme:'dark',reducedMotion:'reduce'});
  await page.screenshot({path:'output/playwright/refined-dark.png',fullPage:true});
  return 'PASS: 63 rounds, early breakdown, stable polling, next/previous, whole-row & keyboard selection, return to latest, narrow layout';
}
